import React, { useState } from "react";
import axios from "axios";

const InputForm = ({ setPredictionData, setRecommendations }) => {
  const [formData, setFormData] = useState({
    age: "",
    gender: "Male",
    device_type: "Phone",
    educational_screentime: "",
    recreational_screentime: ""
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      // Call /predict endpoint
      const predictRes = await axios.post("http://127.0.0.1:8000/predict", formData);
      setPredictionData(predictRes.data);

      // Call /recommend endpoint
      const recRes = await axios.post("http://127.0.0.1:8000/recommend", formData);
      setRecommendations(recRes.data.recommendations);
    } catch (err) {
      console.error(err);
      alert("Error fetching prediction. Make sure the backend is running.");
    }
  };

  return (
    <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
      <label>Age:
        <input type="number" name="age" value={formData.age} onChange={handleChange} required />
      </label>

      <label>Gender:
        <select name="gender" value={formData.gender} onChange={handleChange}>
          <option>Male</option>
          <option>Female</option>
        </select>
      </label>

      <label>Device Type:
        <select name="device_type" value={formData.device_type} onChange={handleChange}>
          <option>Phone</option>
          <option>Tablet</option>
          <option>TV</option>
        </select>
      </label>

      <label>Educational Screen Time (hours):
        <input type="number" step="0.1" name="educational_screentime" value={formData.educational_screentime} onChange={handleChange} required />
      </label>

      <label>Recreational Screen Time (hours):
        <input type="number" step="0.1" name="recreational_screentime" value={formData.recreational_screentime} onChange={handleChange} required />
      </label>

      <button type="submit" style={{ padding: "10px", backgroundColor: "#4CAF50", color: "white", border: "none", cursor: "pointer" }}>Predict</button>
    </form>
  );
};

export default InputForm;
